$ErrorActionPreference = 'Stop'
$issues = [System.Collections.Generic.List[object]]::new()
$names = @('*Audio*','*Kernel-PnP*')
$logs = foreach ($name in $names) {
    try { Get-WinEvent -ListLog $name -ErrorAction Stop | Select-Object LogName,IsEnabled,RecordCount,LogType,LogMode,MaximumSizeInBytes,LastWriteTime,ProviderNames }
    catch { $issues.Add([ordered]@{scope='ListLog';pattern=$name;error=$_.Exception.Message}) }
}
$providers = foreach ($name in @('Microsoft-Windows-Audio*','Microsoft-Windows-Kernel-PnP')) {
    try { Get-WinEvent -ListProvider $name -ErrorAction Stop | ForEach-Object { [ordered]@{name=$_.Name;log_links=@($_.LogLinks | Select-Object LogName,DisplayName,IsImported);message_file=$_.MessageFilePath;resource_file=$_.ResourceFilePath} } }
    catch { $issues.Add([ordered]@{scope='ListProvider';pattern=$name;error=$_.Exception.Message}) }
}
$os = Get-CimInstance Win32_OperatingSystem | Select-Object Caption,Version,BuildNumber,LastBootUpTime
[ordered]@{observed_utc=[datetime]::UtcNow.ToString('o');local_time=[datetime]::Now.ToString('o');time_zone=(Get-TimeZone).Id;session_id=(Get-Process -Id $PID).SessionId;session_name=$env:SESSIONNAME;os=$os;logs=@($logs);providers=@($providers);issues=@($issues)} | ConvertTo-Json -Depth 9

$ErrorActionPreference = 'Stop'
$base = $PSScriptRoot
$spec = Get-Content -LiteralPath ($base+'\event_query_spec.json') -Raw | ConvertFrom-Json
$queries = foreach ($query in $spec.queries) {
    $rows = @(); $errorText = $null; $errorId = $null
    try { $rows = @(Get-WinEvent -LogName $query.log -FilterXPath $query.xpath -MaxEvents $spec.fetch_cap -ErrorAction Stop) }
    catch { $errorText=$_.Exception.Message; $errorId=$_.FullyQualifiedErrorId }
    $events = foreach ($event in $rows) {
        $xml = $event.ToXml()
        [xml]$parsed = $xml
        $fields = @($parsed.Event.EventData.Data | ForEach-Object { [ordered]@{name=$_.Name;value=$_.InnerText} })
        $message = $null; $messageError = $null
        try { $message=$event.FormatDescription() } catch { $messageError=$_.Exception.Message }
        [ordered]@{record_id=$event.RecordId;id=$event.Id;version=$event.Version;provider=$event.ProviderName;log=$event.LogName;time_utc=$event.TimeCreated.ToUniversalTime().ToString('o');level=$event.Level;level_name=$event.LevelDisplayName;task=$event.Task;task_name=$event.TaskDisplayName;process_id=$event.ProcessId;thread_id=$event.ThreadId;message=$message;message_error=$messageError;event_data=$fields;xml=$xml}
    }
    [ordered]@{query_id=$query.id;log=$query.log;xpath=$query.xpath;fetch_cap=$spec.fetch_cap;returned_count=$rows.Count;cap_reached=($rows.Count -eq $spec.fetch_cap);error_id=$errorId;error_text=$errorText;events=@($events)}
}
[ordered]@{observed_utc=[datetime]::UtcNow.ToString('o');pid=$PID;session_id=(Get-Process -Id $PID).SessionId;session_name=$env:SESSIONNAME;window_start_utc=$spec.window_start_utc;window_end_utc=$spec.window_end_utc;scope='Existing enabled Audio channels; Kernel-PnP channels filtered to exact retained audio instance IDs/class GUIDs. No System/Security/Application queries, no log/ETW enablement.';queries=@($queries)} | ConvertTo-Json -Depth 12

$ErrorActionPreference = 'Stop'
$rows = foreach ($name in @('Audiosrv','AudioEndpointBuilder')) {
    $service = Get-CimInstance Win32_Service -Filter "Name='$name'" | Select-Object Name,State,StartMode,ProcessId,PathName,StartName,ServiceType,ExitCode,ServiceSpecificExitCode
    $process = if ($service.ProcessId -gt 0) { Get-CimInstance Win32_Process -Filter "ProcessId=$($service.ProcessId)" | Select-Object ProcessId,ParentProcessId,SessionId,ExecutablePath,CommandLine,CreationDate }
    $key = 'HKLM:\SYSTEM\CurrentControlSet\Services\' + $name
    $config = Get-ItemProperty -LiteralPath $key | Select-Object ImagePath,ObjectName,Start,Type,DependOnService,DependOnGroup,ErrorControl
    $parameters = Get-ItemProperty -LiteralPath ($key+'\Parameters') | Select-Object ServiceDll,ServiceDllUnloadOnStop,ServiceMain
    $path = [Environment]::ExpandEnvironmentVariables($parameters.ServiceDll)
    $item = Get-Item -LiteralPath $path
    $signature = $null; $signatureError = $null
    try { $signature = Get-AuthenticodeSignature -LiteralPath $path } catch { $signatureError = $_.Exception.Message }
    $hasher = [System.Security.Cryptography.SHA256]::Create()
    try { $hash = -join ($hasher.ComputeHash([System.IO.File]::ReadAllBytes($path)) | ForEach-Object { $_.ToString('x2') }) } finally { $hasher.Dispose() }
    $identity = [ordered]@{path=$item.FullName;bytes=$item.Length;sha256=$hash;last_write_utc=$item.LastWriteTimeUtc.ToString('o');file_version=$item.VersionInfo.FileVersion;product_version=$item.VersionInfo.ProductVersion;original_filename=$item.VersionInfo.OriginalFilename;company=$item.VersionInfo.CompanyName;signature_query_error=$signatureError;signature_status=$(if ($signature) { $signature.Status.ToString() } else { $null });signature_message=$signature.StatusMessage;signature_type=$(if ($signature) { $signature.SignatureType.ToString() } else { $null });signer_subject=$signature.SignerCertificate.Subject;signer_issuer=$signature.SignerCertificate.Issuer;signer_thumbprint=$signature.SignerCertificate.Thumbprint}
    $dependencies = @(foreach ($dependency in $config.DependOnService) { Get-CimInstance Win32_Service -Filter "Name='$dependency'" | Select-Object Name,State,StartMode,ServiceType,ExitCode,ServiceSpecificExitCode })
    $sc = foreach ($verb in @('qc','queryex','qtriggerinfo')) { $raw = & sc.exe $verb $name 2>&1 | Out-String; [ordered]@{command="sc.exe $verb $name";exit_code=$LASTEXITCODE;raw_text=$raw} }
    [ordered]@{name=$name;service=$service;hosting_process=$process;service_registry_path=$key;config=$config;parameters=$parameters;dependencies=$dependencies;service_dll=$identity;sc_readonly_queries=@($sc)}
}
$classDefinitions = foreach ($guid in @('{4d36e96c-e325-11ce-bfc1-08002be10318}','{c166523c-fe0c-4a94-a586-f1a80cfbbf3e}')) { $path='HKLM:\SYSTEM\CurrentControlSet\Control\Class\'+$guid; [ordered]@{guid=$guid;registry_path=$path;values=(Get-ItemProperty -LiteralPath $path | Select-Object Class,ClassDesc)} }
[ordered]@{observed_utc=[datetime]::UtcNow.ToString('o');pid=$PID;session_id=(Get-Process -Id $PID).SessionId;session_name=$env:SESSIONNAME;query_scope='Only Audiosrv/AudioEndpointBuilder, their exact current hosting PIDs, declared dependencies, exact service keys and configured ServiceDll files; exact Media/AudioEndpoint class definitions to verify log filters. No modules or broad process scan.';audio_class_definitions=@($classDefinitions);services=@($rows)} | ConvertTo-Json -Depth 10
